{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.FACT_PARETO_SLAB_PERFORMANCE AS WITH ITEM_SLABS AS ( SELECT S.BRANCH_CODE, COALESCE(M.STORE_NAME, CONCAT(\'STORE_\', S.BRANCH_CODE)) AS STORE_NAME, COALESCE(M.CLUSTER_NAME, \'UNMAPPED_CLUSTER\') AS CLUSTER_NAME, CASE WHEN UPPER(TRIM(S.CATEGORY)) IN (\'CHINO\', \'CHINOS\', \'TROUSER\', \'TROUSERS\') THEN \'TROUSERS\' WHEN UPPER(TRIM(S.CATEGORY)) IN (\'DENIM\', \'DENIMS\', \'DEMIN\', \'DEMINS\', \'JEAN\', \'JEANS\') THEN \'JEANS\' ELSE UPPER(TRIM(S.CATEGORY)) END AS CATEGORY, S.SHIPPING_QUANTITY AS QUANTITY, S.SELLING_PRICE AS PRICE, (S.SHIPPING_QUANTITY * S.SELLING_PRICE) AS REVENUE, R.PRICE_SLAB_CODE, R.PRICE_RANGE_LABEL FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE S INNER JOIN SNITCH_DB.MAPLEMONK.REF_CATEGORY_PRICE_SLABS R ON ( CASE WHEN UPPER(TRIM(S.CATEGORY)) IN (\'CHINO\', \'CHINOS\', \'TROUSER\', \'TROUSERS\') THEN \'TROUSERS\' WHEN UPPER(TRIM(S.CATEGORY)) IN (\'DENIM\', \'DENIMS\', \'DEMIN\', \'DEMINS\', \'JEAN\', \'JEANS\') THEN \'JEANS\' ELSE UPPER(TRIM(S.CATEGORY)) END ) = R.CATEGORY AND S.SELLING_PRICE >= R.SLAB_MIN_PRICE AND S.SELLING_PRICE <= R.SLAB_MAX_PRICE LEFT JOIN SNITCH_DB.MAPLEMONK.STORE_ZONE_MAP M ON CAST(S.BRANCH_CODE AS VARCHAR) = CAST(M.BRANCH_CODE AS VARCHAR) WHERE LOWER(S.ORDER_STATUS) LIKE \'%process%\' AND S.DOC_PREFIX NOT IN (\'OMS\',\'QCOM\') ), UNIFIED_AGGREGATE AS ( SELECT \'1. Company Wide\' AS HIERARCHY_LEVEL, \'ALL STORES\' AS LOCATION_ID, \'National (All Stores)\' AS LOCATION_NAME, CATEGORY, PRICE_SLAB_CODE, PRICE_RANGE_LABEL, SUM(QUANTITY) AS SALES_UNITS, SUM(REVENUE) AS SALES_REVENUE FROM ITEM_SLABS GROUP BY CATEGORY, PRICE_SLAB_CODE, PRICE_RANGE_LABEL UNION ALL SELECT \'2. Cluster Wise\' AS HIERARCHY_LEVEL, CLUSTER_NAME AS LOCATION_ID, CONCAT(CLUSTER_NAME, \' Cluster\') AS LOCATION_NAME, CATEGORY, PRICE_SLAB_CODE, PRICE_RANGE_LABEL, SUM(QUANTITY) AS SALES_UNITS, SUM(REVENUE) AS SALES_REVENUE FROM ITEM_SLABS GROUP BY CLUSTER_NAME, CATEGORY, PRICE_SLAB_CODE, PRICE_RANGE_LABEL UNION ALL SELECT \'3. Store Wise\' AS HIERARCHY_LEVEL, CAST(BRANCH_CODE AS VARCHAR) AS LOCATION_ID, STORE_NAME AS LOCATION_NAME, CATEGORY, PRICE_SLAB_CODE, PRICE_RANGE_LABEL, SUM(QUANTITY) AS SALES_UNITS, SUM(REVENUE) AS SALES_REVENUE FROM ITEM_SLABS GROUP BY BRANCH_CODE, STORE_NAME, CATEGORY, PRICE_SLAB_CODE, PRICE_RANGE_LABEL ), PARETO_CALC AS ( SELECT HIERARCHY_LEVEL, LOCATION_ID, LOCATION_NAME, CATEGORY, PRICE_SLAB_CODE, PRICE_RANGE_LABEL, SALES_UNITS, SALES_REVENUE, ROUND(100.0 * SALES_UNITS / NULLIF(SUM(SALES_UNITS) OVER (PARTITION BY HIERARCHY_LEVEL, LOCATION_ID, CATEGORY), 0), 2) AS SALES_SHARE_PCT, SUM(SALES_UNITS) OVER ( PARTITION BY HIERARCHY_LEVEL, LOCATION_ID, CATEGORY ORDER BY SALES_UNITS DESC, PRICE_SLAB_CODE ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) / NULLIF(SUM(SALES_UNITS) OVER (PARTITION BY HIERARCHY_LEVEL, LOCATION_ID, CATEGORY), 0) AS CUMULATIVE_SHARE FROM UNIFIED_AGGREGATE ) SELECT HIERARCHY_LEVEL, LOCATION_ID, LOCATION_NAME, CATEGORY, PRICE_SLAB_CODE, PRICE_RANGE_LABEL, SALES_UNITS, SALES_REVENUE, SALES_SHARE_PCT, ROUND(CUMULATIVE_SHARE * 100, 2) AS CUMULATIVE_SHARE_PCT, CASE WHEN CUMULATIVE_SHARE <= 0.50 THEN \'A\' WHEN CUMULATIVE_SHARE <= 0.80 THEN \'B\' WHEN CUMULATIVE_SHARE <= 0.95 THEN \'C\' ELSE \'D\' END AS PARETO_ABCD_RANK, CURRENT_TIMESTAMP() AS UPDATED_AT FROM PARETO_CALC;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            